#nullable enable // autogenerated

using System.Linq;
using MVZ2.GameContent.Customize;
using MVZ2.Vanilla.Level;
using MVZ2Logic;
using MVZ2Logic.Modding;
using MVZ2Logic.Saves;
using PVZEngine.Callbacks;

namespace MVZ2.GameContent.GlobalCallbacks
{
    [ModGlobalCallbacks]
    public class TeleporterTeamCallbacks : VanillaGlobalCallbacks
    {
        public override void Apply(Mod mod)
        {
            mod.AddTrigger(LevelCallbacks.POST_LEVEL_START, PostLevelStartCallback);
        }
        private void PostLevelStartCallback(LevelCallbackParams param, CallbackResult result)
        {
            var level = param.level;
            var team = Global.Saves.GetTeleporterTeam();
            if (team != null)
            {
                var indexes = team.GetTileIndexes();
                var maxIndex = indexes.Max() + 1;
                var tiles = new TeleporterTeamTileLevelData[maxIndex];
                foreach (var index in indexes)
                {
                    var tile = team.GetTile(index);
                    if (tile == null)
                        continue;
                    var entities = tile.GetEntities();
                    tiles[index] = new TeleporterTeamTileLevelData(entities);
                }
                var teamData = new TeleporterTeamLevelData(tiles);
                level.SetCurrentTeleporterTeam(teamData);
            }
        }
    }
}
